<?php
declare(strict_types=1);
function process_mapping_status_class(string$status):string{return'map-status-'.preg_replace('/[^a-z0-9_-]/','-',strtolower($status));}
function process_mapping_render_svg(array$model,bool$designer=false):void
{
    if(!$model){render_empty_state('No process map','Create or select a process template.');return;}$lanes=$model['lanes'];$steps=$model['steps'];$transitions=$model['transitions'];$laneHeight=160;$height=max(420,80+count($lanes)*$laneHeight);$width=1720;$stepById=[];foreach($steps as$s)$stepById[(int)$s['id']]=$s;
    ?><div class="process-map-shell" data-process-map-shell><div class="process-map-toolbar"><button type="button" class="button ghost" data-map-zoom="in">Zoom in</button><button type="button" class="button ghost" data-map-zoom="out">Zoom out</button><button type="button" class="button ghost" data-map-fit>Fit</button><button type="button" class="button secondary" data-map-fullscreen>Fullscreen</button><span><?= h($designer?'Designer mode':'Live process view') ?></span></div><div class="process-map-viewport" data-map-viewport><svg class="process-map" viewBox="0 0 <?= $width ?> <?= $height ?>" data-process-svg data-designer="<?= $designer?'1':'0' ?>" role="img" aria-label="<?= h($model['process']['process_name']) ?> process swimlane diagram"><defs><marker id="processArrow" markerWidth="10" markerHeight="10" refX="9" refY="3" orient="auto"><path d="M0,0 L0,6 L9,3 z"></path></marker></defs><?php foreach($lanes as$i=>$lane):$y=40+$i*$laneHeight; ?><g class="process-lane <?= h($lane['color_token']) ?>"><rect x="0" y="<?= $y ?>" width="<?= $width ?>" height="<?= $laneHeight ?>" rx="10"></rect><text x="18" y="<?= $y+34 ?>" class="lane-title"><?= h($lane['lane_name']) ?></text><text x="18" y="<?= $y+58 ?>" class="lane-meta"><?= h(status_label($lane['participant_type'])) ?><?= $lane['role_code']?' · '.h(status_label($lane['role_code'])):'' ?></text></g><?php endforeach; ?><?php foreach($transitions as$t):$from=$stepById[(int)$t['from_step_id']]??null;$to=$stepById[(int)$t['to_step_id']]??null;if(!$from||!$to)continue;$x1=(int)$from['position_x']+(int)$from['node_width'];$y1=(int)$from['position_y']+36;$x2=(int)$to['position_x'];$y2=(int)$to['position_y']+36;$mid=($x1+$x2)/2; ?><g class="process-transition <?= !empty($t['is_exception_path'])?'exception':'' ?>"><path d="M<?= $x1 ?> <?= $y1 ?> C<?= $mid ?> <?= $y1 ?> <?= $mid ?> <?= $y2 ?> <?= $x2 ?> <?= $y2 ?>" marker-end="url(#processArrow)"></path><text x="<?= $mid ?>" y="<?= min($y1,$y2)-8 ?>"><?= h($t['condition_label']) ?></text></g><?php endforeach; ?><?php foreach($steps as$s):$status=$s['runtime_status']??'not_started';$draggable=$designer&&$model['version']['status']!=='published'; ?><g class="process-node node-type-<?= h($s['step_type']) ?> <?= h(process_mapping_status_class($status)) ?>" transform="translate(<?= (int)$s['position_x'] ?> <?= (int)$s['position_y'] ?>)" data-process-node data-step-id="<?= (int)$s['id'] ?>" data-step-name="<?= h($s['step_name']) ?>" data-step-type="<?= h($s['step_type']) ?>" data-step-status="<?= h($status) ?>" data-permission="<?= h($s['required_permission']) ?>" data-sla="<?= (int)$s['sla_minutes'] ?>" data-evidence="<?= !empty($s['evidence_required'])?'Required':'Optional' ?>" data-record-type="<?= h($s['canonical_record_type']) ?>" data-draggable="<?= $draggable?'true':'false' ?>" tabindex="0"><rect width="<?= (int)$s['node_width'] ?>" height="<?= (int)$s['node_height'] ?>" rx="14"></rect><text x="14" y="22" class="node-type"><?= h(strtoupper($s['step_type'])) ?></text><text x="14" y="43" class="node-title"><?= h(mb_strimwidth($s['step_name'],0,24,'…')) ?></text><text x="14" y="61" class="node-status"><?= h(status_label($status)) ?></text><?php if($s['step_type']==='gateway'): ?><path class="gateway-mark" d="M124 18 L138 36 L124 54 L110 36 Z"></path><?php endif; ?></g><?php endforeach; ?></svg></div></div><?php
}
function process_mapping_render_styles():void{?><style>
.process-summary{display:grid;grid-template-columns:repeat(7,minmax(120px,1fr));gap:12px;margin-bottom:18px}.process-summary article{background:#fff;border:1px solid #dbe1e8;border-radius:14px;padding:16px}.process-summary span{display:block;color:#667085;font-size:12px}.process-summary strong{display:block;font-size:24px;margin-top:5px}.process-map-shell{background:#fff;border:1px solid #d9e0e7;border-radius:16px;overflow:hidden}.process-map-toolbar{display:flex;gap:8px;align-items:center;padding:12px;border-bottom:1px solid #e5e7eb;background:#f8fafc}.process-map-toolbar span{margin-left:auto;color:#667085}.process-map-viewport{overflow:auto;max-height:720px;background:linear-gradient(#f8fafc 1px,transparent 1px),linear-gradient(90deg,#f8fafc 1px,transparent 1px);background-size:24px 24px}.process-map{min-width:1180px;width:100%;height:auto;display:block}.process-lane rect{fill:#fbfcfe;stroke:#e5e7eb}.process-lane:nth-of-type(even) rect{fill:#f7f9fc}.lane-title{font-size:15px;font-weight:700;fill:#111827}.lane-meta{font-size:11px;fill:#667085}.process-transition path{fill:none;stroke:#667085;stroke-width:2}.process-transition.exception path{stroke:#b42318;stroke-dasharray:7 5}.process-transition text{font-size:10px;fill:#475467;text-anchor:middle}.process-node{cursor:pointer}.process-node[data-draggable="true"]{cursor:grab}.process-node rect{fill:#fff;stroke:#667085;stroke-width:2;filter:drop-shadow(0 4px 8px rgba(15,23,42,.08))}.process-node .node-type{font-size:9px;fill:#667085;font-weight:700}.process-node .node-title{font-size:12px;fill:#111827;font-weight:700}.process-node .node-status{font-size:10px;fill:#475467}.node-type-start rect,.node-type-end rect{fill:#ecfdf3;stroke:#027a48}.node-type-gateway rect{fill:#fffaeb;stroke:#b54708}.node-type-approval rect{fill:#f4f3ff;stroke:#6938ef}.node-type-integration rect,.node-type-external rect{fill:#eff8ff;stroke:#175cd3}.node-type-exception rect{fill:#fef3f2;stroke:#b42318}.node-type-control rect{fill:#fdf2fa;stroke:#c11574}.map-status-completed rect{stroke:#027a48;stroke-width:3}.map-status-active rect{stroke:#f79009;stroke-width:4}.map-status-exception rect,.map-status-blocked rect{stroke:#d92d20;stroke-width:4}.gateway-mark{fill:#f79009;opacity:.22}.process-workspace-grid{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:16px}.process-inspector{background:#fff;border:1px solid #d9e0e7;border-radius:16px;padding:18px;position:sticky;top:16px;align-self:start}.process-inspector dl{display:grid;gap:10px}.process-inspector div{border-bottom:1px solid #eef2f6;padding-bottom:8px}.process-inspector dt{font-size:11px;color:#667085}.process-inspector dd{margin:4px 0 0;font-weight:600}.process-palette{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px}.process-palette button{border:1px solid #d0d5dd;background:#fff;border-radius:999px;padding:8px 12px}.process-template-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.process-template-card{background:#fff;border:1px solid #d9e0e7;border-radius:16px;padding:18px}.process-template-card h3{margin:4px 0 8px}.process-template-card ul{padding-left:18px;color:#475467}.process-status-dot{width:9px;height:9px;border-radius:50%;display:inline-block;margin-right:6px;background:#98a2b3}.process-status-dot.active{background:#f79009}.process-status-dot.completed{background:#12b76a}.process-status-dot.blocked{background:#f04438}.process-analytics-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.process-bar{height:9px;background:#eef2f6;border-radius:99px;overflow:hidden}.process-bar i{display:block;height:100%;background:#344054}.process-map-shell:fullscreen{background:#fff;padding:18px}.process-map-shell:fullscreen .process-map-viewport{max-height:calc(100vh - 90px)}@media(max-width:1100px){.process-summary{grid-template-columns:repeat(3,1fr)}.process-workspace-grid,.process-analytics-grid{grid-template-columns:1fr}.process-template-grid{grid-template-columns:1fr 1fr}}@media(max-width:700px){.process-summary,.process-template-grid{grid-template-columns:1fr}.process-map-toolbar{flex-wrap:wrap}.process-map-toolbar span{width:100%;margin:0}}
</style><?php }
